JCL - 9fad1c64af based on jdk-12.0.1+12)
Summary of problem
The JVMTI event `JVMTI_EVENT_EXCEPTION` is generated multiple times for a single exception. If a native method returns and an exception is currently pending, the JVMTI event is generated, even if it has already been generated.
The [JVMTI documentation]( indicates, that only one event should be generated and the OpenJDK HotSpot VM only generates one event.
The behavior is the same for all OpenJ9 versions available from Please see the example application and JVMTI agent at the end.
Output of the example application
OpenJ9:
MAIN
JVMTI_EVENT_EXCEPTION!
JVMTI_EVENT_EXCEPTION!
JVMTI_EVENT_EXCEPTION!
JVMTI_EVENT_EXCEPTION!
JVMTI_EVENT_EXCEPTION!
JVMTI_EVENT_EXCEPTION!
OpenJDK:
MAIN
JVMTI_EVENT_EXCEPTION!
Example application
Java
// Test.java
class Test {
 private static final boolean USE_NATIVE = true;
 public static void main(String[] args) throws Exception {
 System.out.println("MAIN");
 try { doCall("rec1"); }
 catch (UnsupportedOperationException ignored) {}
 }
 public static final void rec1() { doCall("rec2"); }
 public static final void rec2() { doCall("rec3"); }
 public static final void rec3() { doCall("rec4"); }
 public static final void rec4() { doCall("throwing"); }
 public static final void throwing() { throw new UnsupportedOperationException(); }
 public static void doCall(String methodName) {
 if (USE_NATIVE) { doCall0(methodName); }
 else {
 switch (methodName) {
 case "rec1": rec1(); break;
 case "rec2": rec2(); break;
 case "rec3": rec3(); break;
 case "rec4": rec4(); break;
 case "throwing": throwing(); break;
 }
 }
 }
 public static native void doCall0(String methodName);
}
c++
// test.cpp
#include <cstdio>
#include <jvmti.h>
void JNICALL
on_exception(jvmtiEnv*, JNIEnv*, jthread, jmethodID, jlocation, jobject, jmethodID, jlocation) {
 printf("JVMTI_EVENT_EXCEPTION!\n");
}
JNIEXPORT jint JNICALL
Agent_OnLoad(JavaVM* jvm, char* options, void* reserved) {
 jvmtiEnv* jvmti = nullptr;
 jvm->GetEnv(reinterpret_cast<void**>(&jvmti), JVMTI_VERSION);
 jvmtiCapabilities requiredCaps = {};
 requiredCaps.can_generate_exception_events = 1;
 jvmti->AddCapabilities(&requiredCaps);
 jvmti->SetEventNotificationMode(JVMTI_ENABLE, JVMTI_EVENT_EXCEPTION, nullptr);
 jvmtiEventCallbacks eventCallbacks = {};
 eventCallbacks.Exception = on_exception;
 jvmti->SetEventCallbacks(&eventCallbacks, sizeof(eventCallbacks));
 return 0;
}
extern "C" JNIEXPORT void JNICALL
Java_Test_doCall0(JNIEnv* jni, jclass klass, jstring method_name) {
 const char* method_chars = jni->GetStringUTFChars(method_name, nullptr);
 jmethodID throwingMethod = jni->GetStaticMethodID(klass, method_chars, "()V");
 jni->ReleaseStringUTFChars(method_name, method_chars);
 jni->CallStaticVoidMethod(klass, throwingMethod);
}

