Happens on the latest, 0.18.1, 0.17.0 and I think older builds as well.
public class Test {
 public static void main(String[] args) throws Throwable {
 StringBuffer sb = new StringBuffer(Integer.MAX_VALUE - 8);
 int sz = 16;
 while(true) {
 char[] cbuf = new char[sz];
