Compile and run the following sample files.
The following string is encoded by UTF-8 to attach them to github.
module-info.java
module 字_module {
 exports test.isel;
}
test.java
package test.isel;
public class test{
 public static void method1() {
 System.out.println("method1");
 }
}
test0.java
import test.isel.test;
public class test0{
 public static void main(String[] args) {
 test.method1();
 }
}
$ javac -d mod module-info.java test.java
$ javac -p mod --add-modules 字_module test0.java
Switch the environment to Ja_JP locale.
$ java -p mod --add-modules 字_module test0
java.lang.module.FindException: Module ??_module not found
Expected result:
$ java -p mod --add-modules 字_module test0
method1
