description:
We've noticed that there's a regression in the 15.0.1 release (openj9 0.23), regarding JVMTI `SetNativeMethodPrefix` and `Thread.setNameImpl`.
It works on 15+36 (0.22), but fails on 15.0.1+9 (0.23).
During startup, get the following exception:
Exception in thread "main" java/lang/NullPointerException
 at java/lang/ClassLoader.findNative (java.base@9/ClassLoader.java:1828)
 at java/lang/Thread.setNameImpl (java.base@9/Thread.java:4294967295)
 at java/lang/Thread.<init> (java.base@9/Thread.java:145)
Steps to reproduce:
Java code, that uses ASM to transform the Thread.class file from the 15.0.1 release to add the method:
package com.test;
import org.objectweb.asm.ClassReader;
import org.objectweb.asm.ClassVisitor;
import org.objectweb.asm.ClassWriter;
import org.objectweb.asm.MethodVisitor;
import org.objectweb.asm.Opcodes;
import java.io.ByteArrayInputStream;
import java.lang.reflect.Modifier;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;
public class Main {
 public static void main(String[] args) throws Exception {
 Path inputPath = Paths.get("C:\\Work\\_rebel\\Thread.class");
 Path outputPath = Paths.get("C:\\Work\\_rebel\\Thread_out.class");
 ClassReader cr = new ClassReader(Files.newInputStream(inputPath));
 ClassWriter cw = new ClassWriter(cr, 0);
 cr.accept(new ClassVisitor(Opcodes.ASM9, cw) {
 @Override
 public void visit(int version, int access, String name, String signature, String superName, String[] interfaces) {
 super.visit(Opcodes.V15, access, name, signature, superName, interfaces);
 }
 @Override
 public MethodVisitor visitMethod(int access, String name, String descriptor, String signature, String[] exceptions) {
 if (name.equals("setNameImpl")) {
 MethodVisitor mv = super.visitMethod(access & ~Modifier.NATIVE, name, descriptor, signature, exceptions);
 mv.visitCode();
 mv.visitVarInsn(Opcodes.ALOAD, 0);
 mv.visitVarInsn(Opcodes.LLOAD, 1);
 mv.visitVarInsn(Opcodes.ALOAD, 3);
 mv.visitMethodInsn(Opcodes.INVOKESPECIAL, "java/lang/Thread", "$jni$prefix$" + name, descriptor, false);
 mv.visitInsn(Opcodes.RETURN);
 mv.visitMaxs(4, 4);
 mv.visitEnd();
 return super.visitMethod(access, "$jni$prefix$" + name, descriptor, signature, exceptions);
 }
 else {
 return super.visitMethod(access, name, descriptor, signature, exceptions);
 }
 }
 }, 0);
 byte[] bytes = cw.toByteArray();
 Files.copy(new ByteArrayInputStream(bytes), outputPath, StandardCopyOption.REPLACE_EXISTING);
 }
}
Native agent code that sets the native prefix and replaces the Thread bytes with ones where the method is prefixed:
#include <string.h>
#include <jni.h>
#include <jvmti.h>
static unsigned char* thread_data();
void JNICALL callback_ClassFileLoadHook(jvmtiEnv *jvmti, JNIEnv* env,
 jclass class_being_redefined, jobject loader, const char* name, jobject protection_domain,
 jint class_data_len, const unsigned char* class_data,
 jint* new_class_data_len, unsigned char** new_class_data) {
 if (strcmp("java/lang/Thread", name) == 0) {
 FILE *fp = fopen("C:\\Work\\_rebel\\Thread_out.class", "rb");
 fseek(fp, 0L, SEEK_END);
 *new_class_data_len = ftell(fp);
 (*jvmti)->Allocate(jvmti, *new_class_data_len, new_class_data);
 rewind(fp);
 fread(*new_class_data, *new_class_data_len, 1, fp); fclose(fp);
 }
}
JNIEXPORT jint JNICALL Agent_OnLoad(JavaVM *vm, char *options, void *reserved) {
 jvmtiEnv *jvmti = NULL;
 jint rc = (*vm)->GetEnv(vm, (void **)&jvmti, JVMTI_VERSION_9);
 jvmtiCapabilities caps;
 memset(&caps, 0, sizeof(caps));
 caps.can_set_native_method_prefix = 1;
 caps.can_redefine_classes = 1;
 caps.can_retransform_classes = 1;
 caps.can_generate_all_class_hook_events = 1;
 caps.can_generate_early_vmstart = 1;
 caps.can_generate_early_class_hook_events = 1;
 (*jvmti)->AddCapabilities(jvmti, &caps);
 (*jvmti)->SetNativeMethodPrefix(jvmti, "$jni$prefix$");
 jvmtiEventCallbacks callbacks;
 memset(&callbacks, 0, sizeof(callbacks));
 callbacks.ClassFileLoadHook = &callback_ClassFileLoadHook;
 (*jvmti)->SetEventCallbacks(jvmti, &callbacks, sizeof(callbacks));
 (*jvmti)->SetEventNotificationMode(jvmti, JVMTI_ENABLE, JVMTI_EVENT_CLASS_FILE_LOAD_HOOK, NULL);
 return 0;
}
Works when running on 0.22 / 15+36:
C:\XWork\native-test>"c:\work\jvm\impl\j9-15+36"\bin\java -agentpath:C:\XWork\native-test\build\libs\hello\shared\hello.dll -showversion Main
