@AdamBrousseau @jdekonin fyi

public final class CRIUSupport {
 private CRIUSupport();
 public static CRIUSupport newCRIUSuport();
 public static boolean isCRIUSupportEnabled();
 //throws if failure. CheckPointException if before checkpoint, RestoreException if failure upon restore
 //simply returns if success
 //Exception message will contain system error codes
 public void checkPointJVM() throws UnsupportedOperation, CheckPointException, RestoreException;
 //corresponds to criu_set_images_dir_fd(..)
 public CRIUSupport setImagesDir(Path path) throws SecurityException;
 //corresponds to criu_set_log_file(...)
 public CRIUSupport setLogFile(Path path, String fileName) throws SecurityException;
 //corresponds to criu_set_log_level(..) public CRIUSupport setLogLevel(int level);
 //corresponds to criu_set_file_locks(...)
 public CRIUSupport setFileLocks(boolean fileLocks);
 ....
 //A bunch more of these
 //corresponds to criu_set_leave_running(...)
 public CRIUSupport setLeaveRunning(boolean keepRunning);
 }
So example usage looks something like this:
if (CRIUSupport.isCRIUSupportEnabled()) {
 try {
 CRIUSupport.newCRIUSupport()
 .setImagesDir(checkpointPath)
 .setLogLevel(logPath)
 .checkPointJVM();
 } catch (UnsupportedOperation e) {
 //can get here if isCRIUSupportEnabled is false
 //or if running in mode where a restored JVM is not allowed to checkpoint
 } catch (JVMCheckPointException e) {
 //can get here if there is a JVM failure when attempting to checkpoint
 //exception message will have relevant details
 } catch (SystemCheckPointException e)
 //can get here if there is a CRIU or other System failure when attempting to checkpoint
 //exception message will have relevant details including errcodes
 } catch (RestoreException e) {
 //Can get here is there is a failure when restoring the JVM. //exception message has relevant details
 //Note failures here are non-fatal
 //If a fatal failure occurs the JVM process exits
 }
}

