Eclipse OpenJ9 VM (build master-39c490eaf, JRE 11 Linux amd64-64-Bit Compressed References 20220217_000000 (JIT enabled, AOT enabled)
OpenJ9 - 39c490eaf
OMR - b63287860
JCL - 24e7209ed4 based on jdk-11.0.15+1)
 Testcase1:
java
import java.io.*;
import java.util.*;
public class MyJVMTest{
 static void initCausePlumbing() {
 Throwable t2 = new Throwable("message", new Throwable());
 try {
 t2.initCause(new Throwable());
 } catch (IllegalStateException ise) {
 System.out.println(ise.getCause().equals(t2));
 }
 }
 public static void main(String[] args) {
 initCausePlumbing();
 }
}
 output1:
Exception in thread "main" java.lang.NullPointerException at MyJVMTest.initCausePlumbing(MyJVMTest.java:9) at MyJVMTest.main(MyJVMTest.java:13)
