description:
I'm trying to embed the OpenJ9 JVM in a C++ program, and, I can't close and recreate the JVM. Startup and everything else seems to be fine, but, when I close a JVM with DestroyJavaVM() I get an error.
This error means that successive openings don't operate correctly - which makes other things hard.
I asked on Slack (et al) and ... I guess this is a `generic issue?`
I've attached a standalone example of this happening on Windows.
One of the last lines `jvm->DestroyJavaVM();` returns `JVM_ERR (-1)` after which point the `JNI_CreateJavaVM` calls stop working.
/*
Simple test demonstrating that the OpenJ9 JVM doesn't close/re-open on Windows
Output;
 > starting loop 0 ...
 > EXPECTED ? JNI_OK == destroy_ret
 > starting loop 1 ...
 > REQUIRED ! JNI_OK == create_ret
Tested with
 - JDK 11
 11.0.18.0
 OpenJDK 11.0.18+10
 OpenJ9 0.36.1
 - JDK 19
 18.0.2.1
 OpenJDK 18.0.2+9
 OpenJ9 0.33.1
Builds with a CMake file
 cmake_minimum_required (VERSION 3.26.3)
 project (embed)
 find_package(JNI)
 include_directories(${JNI_INCLUDE_DIRS})
 add_executable(embed embed.cpp)
*/
#include <stdio.h>
#include <stdlib.h>
///
// include JNI and suppress all the warnings it emits
#pragma once
#pragma warning( push )
#pragma warning( suppress : 26451 )
#pragma warning( suppress : 26495 )
#pragma warning( suppress : 26812 )
#include <jni.h>
#pragma warning( pop )
/// // using a function pointer is easier (on Windows)
using create_java_vm_t = jint(JNICALL*)(JavaVM**, void**, void*);
#ifdef _WIN32
# include <string> // to concatenate path strings
# include <Windows.h> // to load functions from a .dll
#endif
///
// assertion macros
// for things that must always be true or we crash
#define REQUIRED(CON) do { if (CON) break; fprintf(stderr, ("REQUIRED ! " #CON "\n")); exit(EXIT_FAILURE); } while(false)
// for things that should be true but we can probably continue without
#define EXPECTED(CON) do { if (CON) break; fprintf(stderr, ("EXPECTED ? " #CON "\n")); } while(false)
int main(int argc, char* argv[])
{
 // find the function pointer
 create_java_vm_t create_java_vm; #ifdef _WIN32
 {
 auto path = std::string(getenv("JAVA_HOME")) + "bin/server/jvm.dll";
 create_java_vm = (create_java_vm_t)GetProcAddress(LoadLibrary(path.c_str()), "JNI_CreateJavaVM");
 }
#else
 {
 // i haven't tested this on not-windows
 create_java_vm = JNI_CreateJavaVM;
 }
#endif
 REQUIRED(nullptr != create_java_vm);
 // create and release the JVM 10 times
 for (int i = 0; i < 10; ++i)
 {
 printf("starting loop %d ...\n", i);
 JavaVMInitArgs args = {};
 args.version = JNI_VERSION_1_2;
 JavaVM* jvm;
 JNIEnv* env;
 // create the jvm
 auto create_ret = create_java_vm(&jvm, (void**)&env, &args);
 REQUIRED(JNI_OK == create_ret);
 // every other time ... run the GC method so we know we're doing something
 if (i % 2)
 {
 auto sys = env->FindClass("java/lang/System");
 REQUIRED(sys);
 auto gc = env->GetStaticMethodID(sys, "gc", "()V");
 REQUIRED(gc);
 env->CallStaticVoidMethod(sys, gc);
 }
 // destroy the jvm
 const auto destroy_ret = jvm->DestroyJavaVM();
 EXPECTED(JNI_OK == destroy_ret);
 }
 printf("... test complete!\n");
 return EXIT_SUCCESS;
}

